Looking at this problem, I need to:

1. Load the graph
2. Identify primary nodes (not replicas of anything)
3. Find customer-facing services deployed in reg-2
4. For each service, determine if it would be down when reg-2 fails
5. A service is down if it's lost OR any node it depends on is lost
6. A node is lost if its replica group's footprint contains only reg-2

Let me trace through the logic:
- Find replica groups (connected components via replicaOf edges)
- For each node, compute its footprint (regions where its replica group is deployed)
- A node is lost when reg-2 fails if footprint == {reg-2}
- A service is down if it's lost or depends on a lost node

```python
import json
from collections import defaultdict, deque

# Load graph
with open('graph.json', 'r') as f:
    graph = json.load(f)

nodes = {node['id']: node for node in graph['nodes']}
edges = graph['edges']

# Build adjacency lists
depends_on = defaultdict(set)  # service -> dependencies
deployed_in = defaultdict(set)  # node -> regions
owned_by = defaultdict(set)
has_sla = defaultdict(set)
replica_of_edges = []  # for building replica groups

for edge in edges:
    source, relation, target = edge
    if relation == 'dependsOn':
        depends_on[source].add(target)
    elif relation == 'deployedIn':
        deployed_in[source].add(target)
    elif relation == 'ownedBy':
        owned_by[source].add(target)
    elif relation == 'hasSLA':
        has_sla[source].add(target)
    elif relation == 'replicaOf':
        replica_of_edges.append((source, target))

# Find replica groups using union-find
parent = {}

def find(x):
    if x not in parent:
        parent[x] = x
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    px, py = find(x), find(y)
    if px != py:
        parent[px] = py

for source, target in replica_of_edges:
    union(source, target)

# Group nodes by replica group
replica_groups = defaultdict(set)
for node_id in nodes:
    root = find(node_id)
    replica_groups[root].add(node_id)

# Compute footprint for each node (footprint of its replica group)
footprint = {}
for node_id in nodes:
    root = find(node_id)
    group = replica_groups[root]
    regions = set()
    for member in group:
        regions.update(deployed_in[member])
    footprint[node_id] = regions

# Identify primary nodes (not replicas)
is_replica = set()
for source, target in replica_of_edges:
    is_replica.add(source)

primary_nodes = {nid for nid in nodes if nid not in is_replica}

# Find customer-facing services in reg-2
customer_facing_services = {nid for nid in nodes 
                            if nodes[nid].get('type') == 'CustomerFacingService' 
                            and 'reg-2' in deployed_in[nid]}

# When reg-2 fails, determine which nodes are lost
lost_nodes = set()
for node_id in nodes:
    if footprint[node_id] == {'reg-2'}:
        lost_nodes.add(node_id)

# Compute transitive dependencies for each service
def get_all_dependencies(service_id, memo=None):
    if memo is None:
        memo = {}
    if service_id in memo:
        return memo[service_id]

    deps = set()
    to_visit = deque([service_id])
    visited = set()

    while to_visit:
        current = to_visit.popleft()
        if current in visited:
            continue
        visited.add(current)

        for dep in depends_on[current]:
            deps.add(dep)
            to_visit.append(dep)

    memo[service_id] = deps
    return deps

# Determine which services are down
down_services = set()
for service_id in customer_facing_services:
    # Service is down if it's lost or depends on a lost node
    if service_id in lost_nodes:
        down_services.add(service_id)
    else:
        all_deps = get_all_dependencies(service_id)
        if any(dep in lost_nodes for dep in all_deps):
            down_services.add(service_id)

# Services NOT down
not_down = customer_facing_services - down_services

result = sorted(list(not_down))
print(json.dumps({"answer_type": "set", "answer": result}))
```

