import json
import networkx as nx

# Read the graph
with open('graph.json', 'r') as f:
    graph_data = json.load(f)

# Create a directed graph
G = nx.DiGraph()

# Add nodes with attributes
for node in graph_data['nodes']:
    node_id = node['id']
    node_type = node['type']
    attrs = {k: v for k, v in node.items() if k not in ['id', 'type']}
    G.add_node(node_id, type=node_type, **attrs)

# Add edges
for edge in graph_data['edges']:
    source, relation, target = edge
    G.add_edge(source, target, relation=relation)

# Find which region svc-785 is deployed in
# We need to find if svc-785 has a "deployedIn" relationship to a region
# or if it depends on something that is deployed in a region

regions = set()

# Check direct deployedIn relationship
for target in G.successors('svc-785'):
    edge_data = G.get_edge_data('svc-785', target)
    if edge_data and edge_data.get('relation') == 'deployedIn':
        if G.nodes[target].get('type') == 'Region':
            regions.add(target)

# If no direct deployment, check if svc-785 depends on services/databases that are deployed
if not regions:
    # Find all nodes that svc-785 depends on (directly or transitively)
    visited = set()
    to_visit = ['svc-785']

    while to_visit:
        current = to_visit.pop(0)
        if current in visited:
            continue
        visited.add(current)

        # Check successors (what current depends on)
        for target in G.successors(current):
            edge_data = G.get_edge_data(current, target)
            if edge_data and edge_data.get('relation') == 'dependsOn':
                to_visit.append(target)
            elif edge_data and edge_data.get('relation') == 'deployedIn':
                if G.nodes[target].get('type') == 'Region':
                    regions.add(target)

    # Also check predecessors for deployedIn
    for node in visited:
        for target in G.successors(node):
            edge_data = G.get_edge_data(node, target)
            if edge_data and edge_data.get('relation') == 'deployedIn':
                if G.nodes[target].get('type') == 'Region':
                    regions.add(target)

answer = sorted(list(regions))
print(json.dumps({"answer_type": "set", "answer": answer}))
